from typing import List
from datetime import date

class Solution:
    def findLoyalCustomers(self, transactions: List[List]) -> List[int]:
        # each transaction: [transaction_id, customer_id, transaction_date(date), amount, transaction_type]
        groups = {}
        for tid, cid, d, amt, typ in transactions:
            groups.setdefault(cid, []).append((d, typ))
        res = []
        for cid, rows in groups.items():
            purchases = sum(1 for _, t in rows if t == 'purchase')
            total = len(rows)
            lo = min(d for d, _ in rows)
            hi = max(d for d, _ in rows)
            if purchases >= 3 and (hi - lo).days >= 30 and (total - purchases) * 100 < total * 20:
                res.append(cid)
        return sorted(res)

