#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // each transaction: {id, customerId, "YYYY-MM-DD", amount, type}
    vector<int> findLoyalCustomers(vector<vector<string>>& transactions) {
        unordered_map<int, vector<pair<string,string>>> g;
        for (auto& t : transactions) {
            int cid = stoi(t[1]);
            g[cid].push_back({t[2], t[4]});
        }
        vector<int> res;
        for (auto& [cid, rows] : g) {
            int purchases = 0;
            string lo = "9999-99-99", hi = "0000-00-00";
            for (auto& [d, ty] : rows) {
                if (ty == "purchase") purchases++;
                lo = min(lo, d); hi = max(hi, d);
            }
            int total = rows.size();
            if (purchases < 3 || daysBetween(lo, hi) < 30) continue;
            if ((total - purchases) * 100LL < (long long)total * 20) res.push_back(cid);
        }
        sort(res.begin(), res.end());
        return res;
    }
private:
    static int daysBetween(const string& a, const string& b) {
        int y1 = stoi(a.substr(0,4)), m1 = stoi(a.substr(5,2)), d1 = stoi(a.substr(8,2));
        int y2 = stoi(b.substr(0,4)), m2 = stoi(b.substr(5,2)), d2 = stoi(b.substr(8,2));
        tm ta = {}, tb = {};
        ta.tm_year = y1 - 1900; ta.tm_mon = m1 - 1; ta.tm_mday = d1;
        tb.tm_year = y2 - 1900; tb.tm_mon = m2 - 1; tb.tm_mday = d2;
        return (int)(difftime(mktime(&tb), mktime(&ta)) / 86400);
    }
};

