import java.util.*;

class Solution {
    public List<Integer> findLoyalCustomers(List<List<Object>> transactions) {
        Map<Integer, List<Object[]>> g = new HashMap<>();
        for (List<Object> t : transactions) {
            int cid = (Integer) t.get(1);
            g.computeIfAbsent(cid, k -> new ArrayList<>()).add(new Object[]{t.get(2), t.get(4)});
        }
        List<Integer> res = new ArrayList<>();
        for (var e : g.entrySet()) {
            int purchases = 0;
            java.time.LocalDate lo = null, hi = null;
            for (Object[] r : e.getValue()) {
                java.time.LocalDate d = (java.time.LocalDate) r[0];
                if (r[1].equals("purchase")) purchases++;
                if (lo == null || d.isBefore(lo)) lo = d;
                if (hi == null || d.isAfter(hi)) hi = d;
            }
            int total = e.getValue().size();
            long refunds = total - purchases;
            if (purchases >= 3 && java.time.temporal.ChronoUnit.DAYS.between(lo, hi) >= 30
                    && refunds * 100 < (long) total * 20) {
                res.add(e.getKey());
            }
        }
        Collections.sort(res);
        return res;
    }
}

