#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    struct St { int pur = 0, tot = 0; string lo = "9999-99-99", hi = "0000-00-00"; };
    vector<int> findLoyalCustomers(vector<vector<string>>& transactions) {
        unordered_map<int, St> st;
        for (auto& t : transactions) {
            int cid = stoi(t[1]);
            auto& s = st[cid];
            s.tot++;
            if (t[4] == "purchase") s.pur++;
            s.lo = min(s.lo, t[2]);
            s.hi = max(s.hi, t[2]);
        }
        vector<int> res;
        for (auto& [cid, s] : st) {
            if (s.pur < 3 || days(s.lo, s.hi) < 30) continue;
            if ((long long)(s.tot - s.pur) * 100 < (long long)s.tot * 20) res.push_back(cid);
        }
        sort(res.begin(), res.end());
        return res;
    }
private:
    static long days(const string& a, const string& b) {
        auto serial = [](const string& d) {
            int y = stoi(d.substr(0,4)), m = stoi(d.substr(5,2)), day = stoi(d.substr(8,2));
            m = (m + 9) % 12; y -= m / 10;
            return 365L * y + y / 4 - y / 100 + y / 400 + (m * 306 + 5) / 10 + day - 1;
        };
        return serial(b) - serial(a);
    }
};

